from __future__ import annotations
from typing import Any, Dict, Optional
from pydantic import model_serializer, model_validator, BaseModel, Field
from sdk.async_exec_api.request_error_code import RequestErrorCode
class RequestError(BaseModel): 
  error: RequestErrorCode = Field(description='''Standardized error codes for API responses. The `*_OTHER_ERROR` family (`CREATE_ORDER_OTHER_ERROR`, `CANCEL_ORDER_OTHER_ERROR`, `CANCEL_ALL_AFTER_OTHER_ERROR`, `MODIFY_ORDER_OTHER_ERROR`) is the per-operation catch-all for a matching-engine-side failure that has no more specific code — the human-readable `message` carries the detail. Modify-specific failures also surface as `INPUT_VALIDATION_ERROR` (bad/immutable restate), `ORDER_NOT_FOUND_ERROR`, `EMPTY_MODIFY_ERROR`, `MODIFY_QTY_BELOW_FILLED_ERROR`, or `POST_ONLY_WOULD_CROSS_ERROR`. Branch-able failure reasons lifted out of the `*_OTHER_ERROR` catch-alls so clients can pick a retry/UX strategy without parsing the free-text `message`: `RATE_LIMITED_ERROR` (request throttled — back off and retry; create/modify/cancel), `INSUFFICIENT_BALANCE_ERROR` (collateral too low for the order; create/modify), `OPEN_ORDER_CAP_ERROR` (the account's resting GTC open-order limit is reached; create), `PRICE_QTY_BOUNDS_ERROR` (price or quantity outside the market's accepted bounds, or a size that would round to an invalid native token amount on a spot market; create/modify), `SERVICE_DISABLED_ERROR` (order entry is disabled for this market/instrument — operational kill-switch or market not enabled; create/modify), `UNAUTHORIZED_ACCOUNT_ERROR` (a valid signer that does not own the target order — distinct from `UNAUTHORIZED_SIGNATURE_ERROR`, which is a bad/unauthorized signature; cancel/modify), `TRADING_HALTED_ERROR` (the market is halted; create/modify), and `DUPLICATE_CLIENT_ORDER_ID_ERROR` (the `clientOrderId` is already in use by a live order; create). Signing deadline and order lifetime are separate fields and have separate codes: `ORDER_DEADLINE_PASSED_ERROR` and `ORDER_DEADLINE_TOO_HIGH_ERROR` are about the signed `deadline` (already in the past, or further into the future than the exchange accepts), while `ORDER_EXPIRES_TOO_SOON_ERROR` is about the order's own `expiresAfter`: a `GTT` order whose expiry has not passed but is too near — it falls inside the settlement window the exchange reserves after admitting an order, so a fill could not settle on chain before the order's own expiry. Nothing has expired; re-sign with a later `expiresAfter` rather than retrying the same order (create/modify). A `GTT` `STOP_LOSS` / `TAKE_PROFIT` is measured against the same reserved window, because its `expiresAfter` is one deadline covering both phases — the armed trigger's lifetime and the fired child's on-chain settlement deadline — so a trigger that could never settle a fill is refused up front rather than armed. That same window also ends both phases early once the trigger is live: firing stops, and a fired child stops matching, one settlement headroom BEFORE `expiresAfter` rather than at it. Pre-trade risk failures each carry their own code, because the remedy differs and a client cannot tell them apart from the free-text `message`. They are evaluated at order entry, before the order can enter the book. An order that fails one is refused in full — there is no partial admission and no reduced accepted quantity — so no order is created, and a refused `modifyOrder` leaves the resting order exactly as it was, at its original price and quantity. Margin capacity, checked in this order: `ACCOUNT_BELOW_LIQUIDATION_MARGIN_ERROR` (the account is already unsafe before the trade: it is below its liquidation margin, or its realized balance is already below the chain's floor — the latter can bind even when unrealized profit keeps the margin balance above liquidation margin, and the `message` states which condition bound. Checked first, so it takes precedence over the others), `ACCOUNT_BELOW_INITIAL_MARGIN_ERROR` (the account would not meet its initial margin requirement after the trade). An account already below initial margin may still trade, but only in a direction that improves its health; an order that does not gets the same code. The initial margin requirement includes a small settlement buffer held against your realized balance. Because unrealized profit does not cover that buffer, an order can fail `ACCOUNT_BELOW_INITIAL_MARGIN_ERROR` even when margin balance on its own would clear the requirement; the `message` states which constraint bound. Open interest: `OPEN_INTEREST_CAP_ERROR` (the market's own open-interest cap, which falls only as positions close and can stay saturated for a long time — surface it rather than retrying) and `OPEN_INTEREST_BUDGET_ERROR` (a tighter budget covering trades matched but not yet settled, which typically clears within seconds; in the current configuration this one binds before the market cap). Reduce-only: `REDUCE_ONLY_CONDITION_NOT_MET_ERROR` (a reduce-only order must strictly reduce the current position, and this one does not; the `message` says how — there is no position to reduce, the order is on the wrong side, or its size would flip the position). Spot: an order the account cannot fund returns the existing `INSUFFICIENT_BALANCE_ERROR`, whereas perp margin failures return the `ACCOUNT_BELOW_*_MARGIN_ERROR` codes above. Malformed orders are not risk failures and keep their existing codes: a reduce-only flag or a trigger order on a spot market, and a reduce-only limit order that is not immediate-or-cancel, are rejected with `INPUT_VALIDATION_ERROR`; a size that would round to an invalid native token amount is rejected with `PRICE_QTY_BOUNDS_ERROR`. Trigger orders (`STOP_LOSS` / `TAKE_PROFIT`) have three rules of their own, none of them a risk failure: `TRIGGER_IOC_MUST_NOT_EXPIRE_ERROR` (an `IOC` trigger create carried an `expiresAfter`. `timeInForce` on a trigger create chooses what the stop becomes when it fires — `IOC`, `GTC` or `GTT` — and only `GTT` has a lifetime: a `GTT` trigger MUST carry a future `expiresAfter`, while `GTC` and `IOC` triggers MUST omit it. Drop the expiry, or switch to `GTT`, and re-sign. The mirror-image mismatches are not trigger-specific and keep the generic code a book order would get: a `GTC` order carrying `expiresAfter`, and a `GTT` order omitting it, are rejected with `INPUT_VALIDATION_ERROR`. In practice the API edge rejects this shape as `INPUT_VALIDATION_ERROR` too, alongside those rules; this code is the matching engine's own stateless guard for the same condition, and it is what surfaces when requests reach the engine directly rather than through the validating edge. Create only: a modify restates `timeInForce` and `expiresAfter` immutably, so a wrong value there is `INPUT_VALIDATION_ERROR` instead), `TRIGGER_LIMIT_OUTSIDE_BAND_ERROR` (the trigger's `limitPx` cannot be admitted against this market's band. Two distinct causes share this code and are separated by the free-text `message`. First, the `limitPx` sits further from its `triggerPx` than a configured band permits: `limitPx` is the worst price the fired child may execute at, and admission enforces `|limitPx − triggerPx| <= triggerPx × band`. The band is a per-market matching-engine setting and is deliberately not published, so move `limitPx` closer to `triggerPx` and re-sign. Second, the market has no trigger band configured at all, in which case the exchange arms no trigger on it and no `limitPx` is admissible. A market whose on-chain fill collar is DISABLED (a zero collar) is the opposite case and admits any positive `limitPx`; the exchange never treats an unconfigured band as a disabled collar. Neither state is published on this API, so a client cannot tell them apart up front — the `message` on the rejection is the signal; create/modify) and `TRIGGER_ALREADY_EXISTS_ERROR` (the account already has an armed trigger of the same `orderType` on that market. The exchange holds at most one stop-loss and one take-profit per position, so a second `STOP_LOSS` — or a second `TAKE_PROFIT` — is refused while the first is armed; the two types never conflict at creation, but they are one-cancels-the-other once live, so whichever fires cancels the other. To move a protective level, modify the armed trigger or cancel it and place a new one; create). Temporarily unavailable: `CROSSING_ORDERS_TEMPORARILY_UNAVAILABLE_ERROR`. Only orders that would cross the book and execute immediately are affected — placing a resting order, modifying one, and cancelling all keep working normally, and your existing resting orders stay in place. The exchange briefly cannot run its pre-trade risk checks — usually just after a restart, or when a required risk input could not be loaded in time — so rather than admit a fill unchecked it rejects the crossing order. Treat it as a pause on new fills rather than an outage; in particular, do not stop cancelling. Retry the crossing order unchanged after a short delay. `UNAVAILABLE_MATCHING_ENGINE_ERROR` is the other one: the request never reached a verdict because a component the exchange needs to admit it was momentarily unusable — the matching-engine transport, the authorization check, or signature verification. Nothing about the request is wrong and nothing was accepted, so retry it unchanged after a short delay rather than re-signing or surfacing it as a rejection. Note that it is returned with HTTP 400 like every other code in this enum; treat the code, not the status, as the retry signal. Retry policy across this enum: retry unchanged, after a short delay, for `CROSSING_ORDERS_TEMPORARILY_UNAVAILABLE_ERROR` and `UNAVAILABLE_MATCHING_ENGINE_ERROR`; back off and retry for `RATE_LIMITED_ERROR`; do not auto-retry the margin, reduce-only or open-interest codes, which need a smaller order, more collateral, or a user decision. The trigger and expiry codes are never retryable unchanged either: `TRIGGER_IOC_MUST_NOT_EXPIRE_ERROR`, `TRIGGER_LIMIT_OUTSIDE_BAND_ERROR` and `ORDER_EXPIRES_TOO_SOON_ERROR` need a corrected, re-signed request, and `TRIGGER_ALREADY_EXISTS_ERROR` needs the existing trigger modified or cancelled first. The exception is a `TRIGGER_LIMIT_OUTSIDE_BAND_ERROR` raised because the market has no band configured at all: no re-signed `limitPx` is admissible there, so surface it as "stops unavailable on this market" rather than re-pricing and retrying. When one of these checks instead cancels an order that is already resting, it does not arrive as an error at all — it arrives on the order as `cancelReason: RISK_CANCELLED`; and when it refuses the child order a trigger is about to fire into, where there is no request to answer, it arrives as `cancelReason: RISK_REJECTED` on both legs of the protective pair, no child having been created.''')
  message: str = Field(description='''Human-readable error message''')
  additional_properties: Optional[dict[str, Any]] = Field(default=None, exclude=True)

  @model_serializer(mode='wrap')
  def custom_serializer(self, handler):
    serialized_self = handler(self)
    additional_properties = getattr(self, "additional_properties")
    if additional_properties is not None:
      for key, value in additional_properties.items():
        # Never overwrite existing values, to avoid clashes
        if not key in serialized_self:
          serialized_self[key] = value

    return serialized_self

  @model_validator(mode='before')
  @classmethod
  def unwrap_additional_properties(cls, data):
    if not isinstance(data, dict):
      data = data.model_dump()
    json_properties = list(data.keys())
    known_object_properties = ['error', 'message', 'additional_properties']
    unknown_object_properties = [element for element in json_properties if element not in known_object_properties]
    # Ignore attempts that validate regular models, only when unknown input is used we add unwrap extensions
    if len(unknown_object_properties) == 0: 
      return data
  
    known_json_properties = ['error', 'message', 'additionalProperties']
    additional_properties = data.get('additional_properties', {})
    for obj_key in unknown_object_properties:
      if not known_json_properties.__contains__(obj_key):
        additional_properties[obj_key] = data.pop(obj_key, None)
    data['additional_properties'] = additional_properties
    return data

